/* Actual input mapping fields keep labels attached and use one comfortable spacing rhythm. */
.input-map-toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:var(--ui-control-gap)}.input-map-toolbar>label{display:flex;align-items:center;gap:var(--ui-control-gap);font-size:var(--type-body);line-height:var(--line-body)}
.input-actions{display:grid;gap:var(--ui-section-gap)}.input-action{min-width:0;display:grid;gap:var(--ui-field-gap);padding-block:var(--ui-field-gap);border-block-end:var(--ui-border-width) solid var(--border-separator)}
.input-action-heading{min-width:0;display:flex;flex-wrap:wrap;align-items:center;gap:var(--ui-control-gap)}.input-action-heading>input{flex:1 1 calc(200px * var(--ui-scale));max-width:var(--ui-field-width)}.input-action-heading>select{width:min(100%,calc(160px * var(--ui-scale)))}.input-action-heading>.icon-action{flex:0 0 var(--ui-control-height)}
.input-binding{min-width:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,calc(240px * var(--ui-scale))),1fr));gap:var(--ui-field-gap);padding-block:var(--ui-field-gap);border-block-end:var(--ui-border-width) solid var(--border-separator)}.input-binding>.icon-action{justify-self:end;align-self:end}
:deep(.binding-field.ui-property-row),.action-advanced-grid :deep(.ui-property-row),.binding-advanced :deep(.ui-property-row){grid-template-columns:minmax(0,1fr);align-items:start;row-gap:var(--ui-label-control-gap)}
.input-conflicts{min-width:0;display:grid;gap:var(--ui-control-gap);padding:var(--ui-panel-inset);border-inline-start:var(--ui-border-width) solid var(--warning);border-radius:var(--radius-control);background:var(--warning-soft);font-size:var(--type-body);line-height:var(--line-body);overflow-wrap:anywhere}
